#[test]
fn type_path_open_is_not_the_free_fn() {
    // Adding a file-level `fn open` must not rebind `RedbStore::open()` in
    // another file. `crate::open()` still follows the unique crate fn.
    let store = MemStore::new();
    let langs = rust_langs();
    let store_rs = RelPath::new("crates/svc-repo/src/store.rs").unwrap();
    let sync_rs = RelPath::new("crates/svc-repo/src/sync.rs").unwrap();
    let mut files = BTreeMap::new();
    files.insert(
        store_rs.clone(),
        b"pub struct RedbStore;\nimpl RedbStore {\n    pub fn open() -> RedbStore { RedbStore }\n}\npub fn open_with() {\n    let _ = RedbStore::open();\n}\npub fn via_crate() {\n    crate::open();\n}\n"
            .to_vec(),
    );
    files.insert(sync_rs.clone(), b"pub fn helper() {}\n".to_vec());
    let before = snapshot_files(&store, &langs, &files, None, ChangeId::new()).unwrap();
    let open_with = named_in_file(&before, "open_with", &store_rs);
    files.insert(sync_rs.clone(), b"pub fn open() {}\n".to_vec());
    let after = snapshot_files(&store, &langs, &files, Some(&before), ChangeId::new()).unwrap();
    assert_eq!(
        after.entities[&open_with].content, before.entities[&open_with].content,
        "RedbStore::open must not rebind to the new fn"
    );
    assert_eq!(
        after.entities[&open_with].bytes, before.entities[&open_with].bytes
    );
    let open_id = named_in_file(&after, "open", &sync_rs);
    let content = store
        .get_content(after.entities[&open_with].content)
        .unwrap();
    assert!(
        !content.tokens.iter().any(|t| matches!(t, Token::Ident(IdentRef::Entity(id)) if *id == open_id)),
        "type path must stay Free, got {:?}",
        content.tokens
    );
    let via = named_in_file(&after, "via_crate", &store_rs);
    let via_c = store.get_content(after.entities[&via].content).unwrap();
    assert!(
        via_c
            .tokens
            .iter()
            .any(|t| matches!(t, Token::Ident(IdentRef::Entity(id)) if *id == open_id)),
        "crate::open still binds, got {:?}",
        via_c.tokens
    );
    let renamed = rename(&store, &after, open_id, "open_store").unwrap();
    let rendered = render(&renamed, &store, &langs, false).unwrap();
    let store_txt = String::from_utf8(rendered.files[&store_rs].clone()).unwrap();
    let sync_txt = String::from_utf8(rendered.files[&sync_rs].clone()).unwrap();
    assert!(store_txt.contains("RedbStore::open()"), "{store_txt}");
    assert!(!store_txt.contains("RedbStore::open_store()"), "{store_txt}");
    assert!(store_txt.contains("crate::open_store()"), "{store_txt}");
    assert!(sync_txt.contains("fn open_store"), "{sync_txt}");
}

crates/svc-core/tests/o4_undo.rs.Text:
//! O4: `undo(op(s)) == s` by restoring the recorded `View` (the oracle set).
//!
//! The repo verb (`svc undo`) also re-renders and groups by changeset; this
//! oracle checks the store law those verbs rest on: after an op, `set_root`
//! + `set_head` from `entry.before` yields the original snapshot hash.

use std::collections::BTreeMap;

use svc_core::engine::{lookup_name, rename, rust_langs, snapshot_files};
use svc_core::ids::{ChangeId, ChangeSetId, RelPath};
use svc_core::op::{Op, OpLogEntry, View};
use svc_core::store::MemStore;
use svc_core::Store;

const SRC: &str = r#"fn parse(s: &str) -> usize { s.len() }
fn load(path: &str) -> usize { parse(path) }
"#;

fn view(store: &MemStore) -> View {
    View {
        root: store.root().unwrap(),
        heads: store.heads().unwrap().into_iter().collect(),
    }
}

fn commit(store: &MemStore, snap: &svc_core::Snapshot) {
    let id = store.put_snapshot(snap).unwrap();
    store.set_root(id).unwrap();
    store.set_head(snap.change, id).unwrap();
}

fn record(store: &MemStore, op: Op, before: View, after: View, group: Option<ChangeSetId>) {
    store
        .append_op(&OpLogEntry {
            op,
            observed: None,
            at: 0,
            group,
            before,
            after,
        })
        .unwrap();
}

fn undo_last(store: &MemStore) {
    let ops = store.ops(svc_core::ids::OpIx(0), true).unwrap();
    let (_, last) = ops.first().expect("oplog");
    if let Some(group) = last.group {
        let mut earliest = last.before.clone();
        for (_, e) in store.ops(svc_core::ids::OpIx(0), false).unwrap() {
            if e.group == Some(group) {
                earliest = e.before;
                break;
            }
        }
        store.set_root(earliest.root).unwrap();
        for (change, snap) in earliest.heads {
            store.set_head(change, snap).unwrap();
        }
        return;
    }
    store.set_root(last.before.root).unwrap();
    for (change, snap) in &last.before.heads {
        store.set_head(*change, *snap).unwrap();
    }
}

#[test]
fn o4_undo_rename_restores_snapshot_hash() {
    let store = MemStore::new();
    let langs = rust_langs();
    let path = RelPath::new("src/lib.rs").unwrap();
    let mut files = BTreeMap::new();
    files.insert(path, SRC.as_bytes().to_vec());
    let change = ChangeId::new();
    let snap = snapshot_files(&store, &langs, &files, None, change).unwrap();
    commit(&store, &snap);
    let origin = store.root().unwrap();

    let parse = lookup_name(&snap, "parse").unwrap();
    let before = view(&store);
    let next = rename(&store, &snap, parse, "parse_config").unwrap();
    commit(&store, &next);
    record(
        &store,
        Op::Rename {
            id: parse,
            new: "parse_config".into(),
        },
        before,
        view(&store),
        None,
    );

    assert_ne!(store.root().unwrap(), origin);
    undo_last(&store);
    assert_eq!(store.root().unwrap(), origin, "undo must restore before.root");
    let restored = store.get_snapshot(store.root().unwrap()).unwrap();
    assert_eq!(restored.entities[&parse].name, "parse");
}

#[test]
fn o4_changeset_undo_restores_the_group_not_one_op() {
    let store = MemStore::new();
    let langs = rust_langs();
    let path = RelPath::new("src/lib.rs").unwrap();
    let mut files = BTreeMap::new();
    files.insert(path, SRC.as_bytes().to_vec());
    let change = ChangeId::new();
    let snap = snapshot_files(&store, &langs, &files, None, change).unwrap();
    commit(&store, &snap);
    let origin = store.root().unwrap();
    let group = Some(ChangeSetId::new());

    let parse = lookup_name(&snap, "parse").unwrap();
    let load = lookup_name(&snap, "load").unwrap();

    let before1 = view(&store);
    let s1 = rename(&store, &snap, parse, "parse_config").unwrap();
    commit(&store, &s1);
    record(
        &store,
        Op::Rename {
            id: parse,
            new: "parse_config".into(),
        },
        before1,
        view(&store),
        group,
    );

    let before2 = view(&store);
    let s2 = rename(&store, &s1, load, "load_cfg").unwrap();
    commit(&store, &s2);
    record(
        &store,
        Op::Rename {
            id: load,
            new: "load_cfg".into(),
        },
        before2,
        view(&store),
        group,
    );

    undo_last(&store);
    assert_eq!(
        store.root().unwrap(),
        origin,
        "group undo must drop both ops, not only the last"
    );
}

crates/svc-core/tests/opaque_identity.rs.Text:
//! `use` lines are opaque entities. Their identity must not depend on where in the
//! file they sit, or every edit above them reads as a semantic change.
use std::collections::BTreeMap;

use svc_core::Kind;
use svc_core::engine::{
    edit_def, lookup_name, merge, rename, render, rust_langs, snapshot_files, status_report,
};
use svc_core::ids::{ChangeId, RelPath};
use svc_core::store::{MemStore, Store};

const SRC: &str =
    "//! crate doc\nuse std::io;\nuse std::fs;\nfn a() { let _ = (io::stdin(), fs::read); }\n";

fn snap(
    store: &MemStore,
    langs: &svc_core::Langs,
    src: &str,
    prev: Option<&svc_core::Snapshot>,
) -> svc_core::Snapshot {
    let mut files = BTreeMap::new();
    files.insert(RelPath::new("src/lib.rs").unwrap(), src.as_bytes().to_vec());
    let change = prev.map(|p| p.change).unwrap_or_else(ChangeId::new);
    snapshot_files(store, langs, &files, prev, change).unwrap()
}

#[test]
fn use_lines_keep_identity_when_text_above_them_changes() {
    let store = MemStore::new();
    let langs = rust_langs();
    let s = snap(&store, &langs, SRC, None);
    let uses: Vec<_> = s
        .entities
        .iter()
        .filter(|(_, r)| r.kind == Kind::Opaque)
        .map(|(id, r)| (*id, r.name.clone()))
        .collect();
    assert_eq!(uses.len(), 2);
    assert!(uses.iter().any(|(_, n)| n == "use std::io;"), "{uses:?}");

    let n = snap(
        &store,
        &langs,
        &SRC.replace("crate doc", "crate doc, one more word"),
        Some(&s),
    );
    for (id, _) in &uses {
        assert!(n.entities.contains_key(id), "use line lost its id");
    }
    let rep = status_report(&store, &s, &n).unwrap();
    assert_eq!(rep.semantic, 0, "{:?}", rep.deltas);
}

#[test]
fn both_sides_editing_above_the_uses_does_not_duplicate_them() {
    let store = MemStore::new();
    let langs = rust_langs();
    let base = snap(&store, &langs, SRC, None);
    let a_fn = lookup_name(&base, "a").unwrap();
    // Side A edits `a`; side B re-ingests with a changed doc line. Both keep the two uses.
    let (a, _) = edit_def(
        &store,
        &langs,
        &base,
        a_fn,
        b"fn a() { let _ = (io::stdin(), fs::read, 1); }\n",
    )
    .unwrap();
    let b = snap(
        &store,
        &langs,
        &SRC.replace("crate doc", "crate doc, edited"),
        Some(&base),
    );
    let (bi, ai, bbi) = (
        store.put_snapshot(&base).unwrap(),
        store.put_snapshot(&a).unwrap(),
        store.put_snapshot(&b).unwrap(),
    );
    let merged = merge(&store, &langs, bi, ai, bbi).unwrap();
    let out = render(&merged, &store, &langs, false).unwrap();
    let text = String::from_utf8(out.files[&RelPath::new("src/lib.rs").unwrap()].clone()).unwrap();
    assert_eq!(text.matches("use std::io;").count(), 1, "{text}");
    assert_eq!(text.matches("use std::fs;").count(), 1, "{text}");
    assert!(merged.conflicts.is_empty(), "{:?}", merged.conflicts);
}

#[test]
fn a_changed_use_line_keeps_its_id() {
    let store = MemStore::new();
    let langs = rust_langs();
    let before = "mod a;\nuse crate::a::f;\nfn main() { f(); }\n";
    let s = snap(&store, &langs, before, None);
    let use_id = s
        .entities
        .iter()
        .find(|(_, r)| r.kind == Kind::Opaque && r.name.contains("crate::a::f"))
        .map(|(id, _)| *id)
        .expect("use line");
    let after = snap(
        &store,
        &langs,
        "mod a;\nuse crate::a::f as ff;\nfn main() { ff(); }\n",
        Some(&s),
    );
    assert!(after.entities.contains_key(&use_id), "use line reminted");
    assert_eq!(after.entities[&use_id].name, "use crate::a::f as ff;");
    let added_use = after
        .entities
        .iter()
        .filter(|(_, r)| r.kind == Kind::Opaque)
        .count();
    assert_eq!(added_use, 1);
}

#[test]
fn rename_of_an_imported_fn_does_not_remint_the_use() {
    let store = MemStore::new();
    let langs = rust_langs();
    let mut files = BTreeMap::new();
    files.insert(
        RelPath::new("src/a.rs").unwrap(),
        b"pub fn f() {}\n".to_vec(),
    );
    files.insert(
        RelPath::new("src/lib.rs").unwrap(),
        b"mod a;\nuse crate::a::f;\nfn main() { f(); }\n".to_vec(),
    );
    let s = snapshot_files(&store, &langs, &files, None, ChangeId::new()).unwrap();
    let use_id = s
        .entities
        .iter()
        .find(|(_, r)| r.kind == Kind::Opaque && r.name.contains("crate::a::f"))
        .map(|(id, _)| *id)
        .expect("use line");
    let f = lookup_name(&s, "f").unwrap();
    let renamed = rename(&store, &s, f, "f2").unwrap();
    let rendered = render(&renamed, &store, &langs, false).unwrap();
    let again = snapshot_files(
        &store,
        &langs,
        &rendered.files,
        Some(&renamed),
        ChangeId::new(),
    )
    .unwrap();
    assert!(
        again.entities.contains_key(&use_id),
        "use line reminted after rename"
    );
    assert!(
        again.entities[&use_id].name.contains("f2"),
        "{}",
        again.entities[&use_id].name
    );
}

crates/svc-core/tests/ops_sigkey.rs.Text:
//! `(parent, kind, name)` identifies an entity across re-parses and in merge, so the
//! verbs that could create a second one refuse. `edit_def` keeps the kind it was given.
use std::collections::BTreeMap;

use svc_core::engine::{
    add_def, edit_def, lookup_name, move_def, rename, rust_langs, snapshot_files,
};
use svc_core::ids::{ChangeId, EntityId, RelPath};
use svc_core::store::MemStore;
use svc_core::{Intent, Kind};

fn fixture(src: &str) -> (MemStore, svc_core::Langs, svc_core::Snapshot) {
    let store = MemStore::new();
    let langs = rust_langs();
    let mut files = BTreeMap::new();
    files.insert(RelPath::new("src/lib.rs").unwrap(), src.as_bytes().to_vec());
    let snap = snapshot_files(&store, &langs, &files, None, ChangeId::new()).unwrap();
    (store, langs, snap)
}

#[test]
fn rename_onto_an_existing_sibling_is_refused() {
    let (store, _, snap) = fixture("fn a() {}\nfn b() {}\n");
    let a = lookup_name(&snap, "a").unwrap();
    let err = rename(&store, &snap, a, "b").unwrap_err().to_string();
    assert!(err.contains("already exists"), "{err}");
    assert!(rename(&store, &snap, a, "c").is_ok());
}

#[test]
fn rename_to_a_name_used_under_another_parent_is_fine() {
    let (store, _, snap) = fixture("struct S;\nimpl S { fn new() -> S { S } }\nfn make() -> S { S }\n");
    let make = lookup_name(&snap, "make").unwrap();
    assert!(
        rename(&store, &snap, make, "new").is_ok(),
        "different parent, no clash"
    );
}

#[test]
fn add_def_of_a_duplicate_is_refused() {
    let (store, langs, snap) = fixture("fn a() {}\n");
    let err = add_def(
        &store,
        &langs,
        &snap,
        EntityId::new(),
        None,
        1,
        b"fn a() -> u32 { 2 }\n",
        Intent::Feature,
    )
    .unwrap_err()
    .to_string();
    assert!(err.contains("already exists"), "{err}");
}

#[test]
fn move_def_into_a_parent_that_has_the_name_is_refused() {
    let (store, langs, snap) = fixture("struct S;\nimpl S { fn go() {} }\nfn go() {}\n");
    let top = lookup_name(&snap, "go").err().map(|e| e.to_string());
    assert!(
        top.is_some_and(|e| e.contains("ambiguous")),
        "two `go`s exist under different parents"
    );
    let imp = snap
        .entities
        .iter()
        .find(|(_, r)| r.kind == Kind::Impl)
        .map(|(id, _)| *id)
        .unwrap();
    let free_go = snap
        .entities
        .iter()
        .find(|(_, r)| r.name == "go" && r.parent.is_none())
        .map(|(id, _)| *id)
        .unwrap();
    let err = move_def(&store, &langs, &snap, free_go, Some(imp), None)
        .unwrap_err()
        .to_string();
    assert!(err.contains("already exists"), "{err}");
}

#[test]
fn edit_def_may_not_change_kind() {
    let (store, langs, snap) = fixture("fn foo() -> u32 { 1 }\n");
    let foo = lookup_name(&snap, "foo").unwrap();
    let err = edit_def(&store, &langs, &snap, foo, b"const foo: u32 = 1;\n")
        .unwrap_err()
        .to_string();
    assert!(err.contains("cannot change"), "{err}");
    let (next, _) = edit_def(&store, &langs, &snap, foo, b"fn foo() -> u32 { 2 }\n").unwrap();
    assert_eq!(next.entities[&foo].kind, Kind::Fn);
}

#[test]
fn snapshot_insert_refuses_a_duplicate_sigkey() {
    let (_, _, snap) = fixture("fn a() {}\n");
    let a = lookup_name(&snap, "a").unwrap();
    let mut rec = snap.entities[&a].clone();
    rec.name = "a".into();
    let mut next = snap.clone();
    let err = next.insert(EntityId::new(), rec).unwrap_err().to_string();
    assert!(err.contains("already exists"), "{err}");
}

#[test]
fn snapshot_insert_refuses_a_missing_file() {
    let (_, _, snap) = fixture("fn a() {}\n");
    let a = lookup_name(&snap, "a").unwrap();
    let mut rec = snap.entities[&a].clone();
    rec.file = RelPath::new("src/gone.rs").unwrap();
    rec.name = "b".into();
    let mut next = snap.clone();
    let err = next.insert(EntityId::new(), rec).unwrap_err().to_string();
    assert!(err.contains("no file record"), "{err}");
}

#[test]
fn delete_refusal_names_the_referrers() {
    use svc_core::engine::{delete, lookup_name};
    let store = MemStore::new();
    let langs = rust_langs();
    let mut files = BTreeMap::new();
    files.insert(
        RelPath::new("src/lib.rs").unwrap(),
        b"fn a() {}\nfn b() { a() }\nfn c() { a(); b() }\n".to_vec(),
    );
    let snap = snapshot_files(&store, &langs, &files, None, ChangeId::new()).unwrap();
    let a = lookup_name(&snap, "a").unwrap();
    let err = delete(&snap, &store, a).unwrap_err().to_string();
    assert!(err.contains("b (src/lib.rs"), "{err}");
    assert!(err.contains("c (src/lib.rs"), "{err}");
    assert!(!err.contains("more"), "{err}");
}

crates/svc-core/tests/sigkey_file_scope..Text:
//! File-level items are unique per file, not per repository: two modules may each
//! define `fn hex32` and both `use serde::Serialize;`. Matching, merge unification
//! and add/add detection all key on that scope.
use std::collections::BTreeMap;

use svc_core::engine::{edit_def, lookup_name, merge, rename, rust_langs, snapshot_files};
use svc_core::ids::{ChangeId, RelPath};
use svc_core::store::{MemStore, Store};
use svc_core::{Conflict, Kind};

fn two_files() -> BTreeMap<RelPath, Vec<u8>> {
    let mut files = BTreeMap::new();
    files.insert(
        RelPath::new("src/a.rs").unwrap(),
        b"use serde::Serialize;\nfn hex32(b: &[u8]) -> String { format!(\"{b:?}\") }\nfn only_a() -> u32 { 1 }\n".to_vec(),
    );
    files.insert(
        RelPath::new("src/b.rs").unwrap(),
        b"use serde::Serialize;\nfn hex32(b: &[u8]) -> String { format!(\"{b:x?}\") }\nfn only_b() -> u32 { 2 }\n".to_vec(),
    );
    files
}

#[test]
fn same_name_in_two_files_keeps_ids_across_reingest() {
    let store = MemStore::new();
    let langs = rust_langs();
    let files = two_files();
    let s = snapshot_files(&store, &langs, &files, None, ChangeId::new()).unwrap();
    let ids: BTreeMap<_, _> = s
        .entities
        .iter()
        .filter(|(_, r)| r.name == "hex32")
        .map(|(id, r)| (r.file.clone(), *id))
        .collect();
    assert_eq!(ids.len(), 2);
    // Re-ingest with b.rs changed above hex32 so file order and content both move.
    let mut again = files.clone();
    again.insert(
        RelPath::new("src/b.rs").unwrap(),
        b"//! b\nuse serde::Serialize;\nfn hex32(b: &[u8]) -> String { format!(\"{b:x?}\") }\nfn only_b() -> u32 { 2 }\n".to_vec(),
    );
    let n = snapshot_files(&store, &langs, &again, Some(&s), s.change).unwrap();
    for (file, id) in &ids {
        let rec = &n.entities[id];
        assert_eq!(&rec.file, file, "hex32 in {file} kept its id");
    }
}

#[test]
fn unrelated_edits_in_two_files_merge_without_add_add() {
    let store = MemStore::new();
    let langs = rust_langs();
    let base = snapshot_files(&store, &langs, &two_files(), None, ChangeId::new()).unwrap();
    let only_a = lookup_name(&base, "only_a").unwrap();
    let only_b = lookup_name(&base, "only_b").unwrap();
    let (a, _) = edit_def(
        &store,
        &langs,
        &base,
        only_a,
        b"fn only_a() -> u32 { 10 }\n",
    )
    .unwrap();
    let (b, _) = edit_def(
        &store,
        &langs,
        &base,
        only_b,
        b"fn only_b() -> u32 { 20 }\n",
    )
    .unwrap();
    let (bi, ai, bbi) = (
        store.put_snapshot(&base).unwrap(),
        store.put_snapshot(&a).unwrap(),
        store.put_snapshot(&b).unwrap(),
    );
    let merged = merge(&store, &langs, bi, ai, bbi).unwrap();
    assert!(merged.conflicts.is_empty(), "{:?}", merged.conflicts);
    assert_eq!(
        merged
            .entities
            .values()
            .filter(|r| r.name == "hex32")
            .count(),
        2
    );
    assert_eq!(
        merged
            .entities
            .values()
            .filter(|r| r.kind == Kind::Opaque)
            .count(),
        2
    );
}

#[test]
fn rename_may_reuse_a_name_taken_in_another_file() {
    let store = MemStore::new();
    let langs = rust_langs();
    let s = snapshot_files(&store, &langs, &two_files(), None, ChangeId::new()).unwrap();
    let only_a = lookup_name(&s, "only_a").unwrap();
    assert!(
        rename(&store, &s, only_a, "only_b").is_ok(),
        "only_b lives in b.rs; a.rs is free to use it"
    );
    let only_b = lookup_name(&s, "only_b").unwrap();
    let hex_in_b = s
        .entities
        .iter()
        .find(|(_, r)| r.name == "hex32" && r.file.as_str() == "src/b.rs")
        .map(|(id, _)| *id)
        .unwrap();
    let err = rename(&store, &s, only_b, "hex32").unwrap_err().to_string();
    assert!(
        err.contains("already exists") && err.contains(&hex_in_b.short()),
        "{err}"
    );
    let _ = Conflict::AddAdd {
        key: s.entities[&only_a].sig_key(),
        a: only_a,
        b: only_a,
    };
}

crates/svc-repo/src/bundle.rs.Text:
//! A history bundle: the op log of one store, written so another checkout of the same tree
//! can replay it into its own store. Typed ops carry themselves; what they cannot carry is
//! resolved on import — entity ids by their path (file, then kind/name from the root
//! down), change ids by the order they are minted — and a hand edit (`Absorb`) carries the
//! files it changed. Every entry names the hash of the tree it left behind, so an import
//! knows at which op, if any, it stopped reproducing the recorded history.
//!
//! `svc history export` writes one; `svc history import` replays one; `demo/history/` keeps
//! the bundles of this repository's own svc-made changes.

use std::collections::BTreeMap;

use serde::{Deserialize, Serialize};
use svc_core::engine::{add_def_at, delete, edit_def, inline, move_def, relocate, render, rename};
use svc_core::{
    ChangeId, ChangeSet, ChangeSetId, EntityId, Error, Kind, NoteTo, Op, OpIx, OpLogEntry, RelPath, Result,
    Snapshot, SnapshotId,
};

use crate::history::{self, op_entity};
use crate::merge;
use crate::repo::{Provenance, Repo};

/// Where an entity sits: its file, then kind and name from the outermost parent down to
/// itself. The same tree ingested twice gives every entity a fresh id; the path is what
/// survives.
#[derive(Clone, Debug, PartialEq, Eq, Serialize, Deserialize)]
pub struct EntityPath {
    pub file: RelPath,
    pub chain: Vec<(Kind, String)>,
}

/// A file a hand edit left: its new bytes (text when UTF-8), or removed.
#[derive(Clone, Debug, PartialEq, Eq, Serialize, Deserialize)]
pub enum FileBody {
    Text(String),
    Bytes(Vec<u8>),
    Removed,
}

#[derive(Clone, Debug, Serialize, Deserialize)]
pub struct BundleEntry {
    pub ix: OpIx,
    pub entry: OpLogEntry,
    /// Every entity id the op names, by path in the tree the op started from (the op's own
    /// new entity, for add-def, is absent: its id is minted by the op).
    #[serde(default)]
    pub refs: BTreeMap<EntityId, EntityPath>,
    /// For `Absorb`: the files the hand edit changed.
    #[serde(default)]
    pub files: BTreeMap<RelPath, FileBody>,
    /// blake3 over the rendered tree after this op (sorted path, bytes).
    pub after_tree: String,
    /// The checkout that made it (`None` = the default one).
    #[serde(default)]
    pub workspace: Option<String>,
}

#[derive(Clone, Debug, Serialize, Deserialize)]
pub struct Bundle {
    /// blake3 of the rendered tree the first entry starts from; an import checks its own.
    pub base_tree: String,
    pub entries: Vec<BundleEntry>,
    /// The changesets the entries belong to, so a replayed op keeps its group's name.
    #[serde(default)]
    pub changesets: Vec<ChangeSet>,
}

#[derive(Clone, Debug, Serialize)]
pub struct ImportReport {
    pub applied: usize,
    /// Ops whose result the engine no longer computes as recorded; the record supplied
    /// the tree instead, so the history still lands as it happened.
    pub from_record: Vec<OpIx>,
    /// First entry whose tree after import differs from the recorded hash even so, if any.
    pub diverged_at: Option<OpIx>,
}

fn tree_hash(files: &BTreeMap<RelPath, Vec<u8>>) -> String {
    let mut h = blake3::Hasher::new();
    for (path, bytes) in files {
        h.update(path.as_str().as_bytes());
        h.update(&[0]);
        h.update(&(bytes.len() as u64).to_le_bytes());
        h.update(bytes);
    }
    h.finalize().to_hex().to_string()
}

fn rendered(repo: &Repo, snap: &Snapshot) -> Result<BTreeMap<RelPath, Vec<u8>>> {
    Ok(render(snap, repo.store(), repo.langs(), false)?.files)
}

fn path_of(snap: &Snapshot, id: EntityId) -> Option<EntityPath> {
    let rec = snap.entities.get(&id)?;
    let mut chain = vec![(rec.kind, rec.name.clone())];
    let mut parent = rec.parent;
    while let Some(p) = parent {
        let pr = snap.entities.get(&p)?;
        chain.push((pr.kind, pr.name.clone()));
        parent = pr.parent;
    }
    chain.reverse();
    Some(EntityPath { file: rec.file.clone(), chain })
}

fn find_by_path(snap: &Snapshot, path: &EntityPath) -> Option<EntityId> {
    snap.entities
        .iter()
        .filter(|(_, r)| r.file == path.file)
        .find(|(id, _)| path_of(snap, **id).as_ref() == Some(path))
        .map(|(id, _)| *id)
}

/// Every entity id an op names besides one it mints itself.
fn named_ids(op: &Op) -> Vec<EntityId> {
    match op {
        Op::Move { id, parent, .. } => std::iter::once(*id).chain(*parent).collect(),
        Op::Extract { id, new_parent, .. } => std::iter::once(*id).chain(*new_parent).collect(),
        Op::AddDef { parent, .. } => parent.iter().copied().collect(),
        _ => op_entity(op).into_iter().collect(),
    }
}

/// The op log from `since` on, with what an import needs beside each entry.
pub fn export(repo: &Repo, since: OpIx) -> Result<Bundle> {
    export_range(repo, since, None)
}

/// [`export`] stopping before `until` (exclusive), for cutting one landing out of a longer log.
pub fn export_range(repo: &Repo, since: OpIx, until: Option<OpIx>) -> Result<Bundle> {
    let mut ops = repo.store().ops(since, false)?;
    if let Some(end) = until {
        ops.retain(|(ix, _)| *ix < end);
    }
    if ops.is_empty() {
        return Err(Error::Other(format!("no ops at or after {}", since.0)));
    }
    export_ops(repo, ops)
}

/// Whether an op is part of a changeset's story: stamped with the group, or a note
/// addressed to it (a review verdict, a claim) — which has no group of its own.
pub fn belongs(e: &OpLogEntry, group: ChangeSetId) -> bool {
    e.group == Some(group) || matches!(&e.op, Op::Note { to: NoteTo::Changeset(id), .. } if *id == group)
}

/// The ops that [`belongs`] to one changeset except those `has` — what a clone that already holds some of the
/// group's ops still lacks. Empty entries when there is nothing to send.
pub fn export_changeset(repo: &Repo, group: ChangeSetId, has: impl Fn(&OpLogEntry) -> bool) -> Result<Bundle> {
    let mut ops = repo.store().ops(OpIx(0), false)?;
    ops.retain(|(_, e)| belongs(e, group) && !has(e));
    if ops.is_empty() {
        let cs = repo.store().get_changeset(group)?;
        return Ok(Bundle { base_tree: String::new(), entries: Vec::new(), changesets: vec![cs] });
    }
    export_ops(repo, ops)
}

fn export_ops(repo: &Repo, ops: Vec<(OpIx, OpLogEntry)>) -> Result<Bundle> {
    let store = repo.store();
    let (_, first) = &ops[0];
    let base = store.get_snapshot(first.before.root)?;
    let base_tree = tree_hash(&rendered(repo, &base)?);
    let mut entries = Vec::with_capacity(ops.len());
    for (ix, e) in &ops {
        let before = store.get_snapshot(e.before.root)?;
        let after = store.get_snapshot(e.after.root)?;
        let after_files = rendered(repo, &after)?;
        let refs = named_ids(&e.op)
            .into_iter()
            .filter_map(|id| path_of(&before, id).map(|p| (id, p)))
            .collect();
        // What the op changed on disk, for every op: an absorb has nothing else, and any
        // other op falls back to it when a later engine no longer computes the same result.
        let before_files = rendered(repo, &before)?;
        let files = changed_files(&before_files, &after_files);
        entries.push(BundleEntry {
            ix: *ix,
            entry: e.clone(),
            refs,
            files,
            after_tree: tree_hash(&after_files),
            workspace: repo.redb().op_workspace(*ix)?.filter(|w| !w.is_empty()),
        });
    }
    let mut changesets = Vec::new();
    for g in entries.iter().filter_map(|b| {
        b.entry.group.or(match &b.entry.op {
            Op::Note {
                to: NoteTo::Changeset(id),
                ..
            } => Some(*id),
            _ => None,
        })
    }) {
        if !changesets.iter().any(|cs: &ChangeSet| cs.id == g)
            && let Ok(cs) = store.get_changeset(g)
        {
            changesets.push(cs);
        }
    }
    Ok(Bundle { base_tree, entries, changesets })
}

/// The files `after` has that `before` did not have with those bytes, and the ones it lost.
fn changed_files(before: &BTreeMap<RelPath, Vec<u8>>, after: &BTreeMap<RelPath, Vec<u8>>) -> BTreeMap<RelPath, FileBody> {
    let mut files = BTreeMap::new();
    for (path, bytes) in after {
        if before.get(path) != Some(bytes) {
            let body = match String::from_utf8(bytes.clone()) {
                Ok(text) => FileBody::Text(text),
                Err(_) => FileBody::Bytes(bytes.clone()),
            };
            files.insert(path.clone(), body);
        }
    }
    for path in before.keys() {
        if !after.contains_key(path) {
            files.insert(path.clone(), FileBody::Removed);
        }
    }
    files
}

struct Import<'a> {
    repo: &'a Repo,
    /// Recorded change id → the one minted here.
    changes: BTreeMap<ChangeId, ChangeId>,
    /// Recorded snapshot id → the one this import produced for it.
    snaps: BTreeMap<SnapshotId, SnapshotId>,
    /// Ops whose result the engine no longer reproduces and the record supplied instead.
    from_record: Vec<OpIx>,
}

impl Import<'_> {
    fn change(&self, c: ChangeId) -> ChangeId {
        *self.changes.get(&c).unwrap_or(&c)
    }

    fn entity(&self, cur: &Snapshot, b: &BundleEntry, id: EntityId) -> Result<EntityId> {
        let path = b.refs.get(&id).ok_or_else(|| {
            Error::Other(format!("op {}: no path recorded for entity {}", b.ix.0, id.short()))
        })?;
        find_by_path(cur, path).ok_or_else(|| {
            Error::Other(format!(
                "op {}: no entity at {} {} in this tree",
                b.ix.0,
                path.file,
                path.chain.iter().map(|(k, n)| format!("{k:?} {n}")).collect::<Vec<_>>().join(" / ")
            ))
        })
    }

    /// The snapshot an op leaves: what the engine computes now, when its tree is the recorded
    /// one; otherwise the recorded files, ingested over the current snapshot — the history
    /// still lands as it happened, and the op is counted as taken from the record.
    fn rewrite(
        &mut self,
        b: &BundleEntry,
        cur: &Snapshot,
        engine: impl FnOnce(&Snapshot) -> Result<Snapshot>,
    ) -> Result<Snapshot> {
        let repo = self.repo;
        let computed = engine(cur)?;
        if b.files.is_empty() || tree_hash(&rendered(repo, &computed)?) == b.after_tree {
            return Ok(computed);
        }
        self.from_record.push(b.ix);
        // In memory, not on disk: a file written now would be absorbed as a hand edit first.
        let mut files = repo.tracked_files()?;
        for (path, body) in &b.files {
            match body {
                FileBody::Removed => {
                    files.remove(path);
                }
                FileBody::Text(t) => {
                    files.insert(path.clone(), t.as_bytes().to_vec());
                }
                FileBody::Bytes(v) => {
                    files.insert(path.clone(), v.clone());
                }
            }
        }
        repo.snapshot_files(&files, Some(cur), cur.change)
    }

    fn apply(&mut self, b: &BundleEntry) -> Result<()> {
        let repo = self.repo;
        let e = &b.entry;
        // A `checkout` between ops is not an op: the entry names the root it started from,
        // and if that is not where the last op left us, switch there first.
        if let Some(from) = self.snaps.get(&e.before.root).copied() {
            if from != repo.store().root()? {
                history::checkout(repo, from)?;
            }
        }
        // Same-snapshot rewrites: the op with its ids mapped, then the engine call the verb
        // itself makes.
        let cur = repo.current()?;
        match &e.op {
            Op::Rename { id, new } => {
                let id = self.entity(&cur, b, *id)?;
                let op = Op::Rename { id, new: new.clone() };
                let next = self.rewrite(b, &cur, |cur| rename(repo.store(), cur, id, new))?;
                repo.mutate(op, e.observed, |repo, cur| repo.amend(cur, next))?;
            }
            Op::Move { id, parent, ordinal } => {
                let id = self.entity(&cur, b, *id)?;
                let parent = parent.map(|p| self.entity(&cur, b, p)).transpose()?;
                let op = Op::Move { id, parent, ordinal: *ordinal };
                let next = self.rewrite(b, &cur, |cur| move_def(repo.store(), repo.langs(), cur, id, parent, *ordinal))?;
                repo.mutate(op, e.observed, |repo, cur| repo.amend(cur, next))?;
            }
            Op::Relocate { id, file, ordinal } => {
                let id = self.entity(&cur, b, *id)?;
                let op = Op::Relocate { id, file: file.clone(), ordinal: *ordinal };
                let next = self.rewrite(b, &cur, |cur| relocate(cur, repo.store(), id, file.clone(), *ordinal))?;
                repo.mutate(op, e.observed, |repo, cur| repo.amend(cur, next))?;
            }
            Op::Extract { id, new_parent, ordinal } => {
                let id = self.entity(&cur, b, *id)?;
                let new_parent = new_parent.map(|p| self.entity(&cur, b, p)).transpose()?;
                let op = Op::Extract { id, new_parent, ordinal: *ordinal };
                let next = self.rewrite(b, &cur, |cur| move_def(repo.store(), repo.langs(), cur, id, new_parent, Some(*ordinal)))?;
                repo.mutate(op, e.observed, |repo, cur| repo.amend(cur, next))?;
            }
            Op::Inline { id } => {
                let id = self.entity(&cur, b, *id)?;
                let next = self.rewrite(b, &cur, |cur| inline(repo.store(), repo.langs(), cur, id))?;
                repo.mutate(Op::Inline { id }, e.observed, |repo, cur| repo.amend(cur, next))?;
            }
            Op::AddDef { id, parent, ordinal, definition, intent, file } => {
                let parent = parent.map(|p| self.entity(&cur, b, p)).transpose()?;
                let (id, ordinal, intent, file) = (*id, *ordinal, intent.clone(), file.clone());
                let op = Op::AddDef {
                    id,
                    parent,
                    ordinal,
                    definition: definition.clone(),
                    intent: intent.clone(),
                    file: file.clone(),
                };
                let next = self.rewrite(b, &cur, |cur| {
                    add_def_at(
                        repo.store(),
                        repo.langs(),
                        cur,
                        id,
                        parent,
                        file.clone(),
                        ordinal,
                        definition.as_bytes(),
                        intent.clone(),
                    )
                })?;
                repo.mutate(op, e.observed, |repo, cur| repo.amend(cur, next))?;
            }
            Op::Delete { id, intent } => {
                let id = self.entity(&cur, b, *id)?;
                let op = Op::Delete { id, intent: intent.clone() };
                let next = self.rewrite(b, &cur, |cur| delete(cur, repo.store(), id))?;
                repo.mutate(op, e.observed, |repo, cur| repo.amend(cur, next))?;
            }
            Op::EditDef { id, definition, intent } => {
                let id = self.entity(&cur, b, *id)?;
                let op = Op::EditDef { id, definition: definition.clone(), intent: intent.clone() };
                let next = self.rewrite(b, &cur, |cur| {
                    edit_def(repo.store(), repo.langs(), cur, id, definition.as_bytes()).map(|(next, _)| next)
                })?;
                repo.mutate(op, e.observed, |repo, cur| repo.amend(cur, next))?;
            }
            Op::New { change } => {
                let out = history::new(repo)?;
                self.changes.insert(*change, out.change);
            }
            Op::Describe { msg } => {
                history::describe(repo, msg)?;
            }
            Op::Branch { name } => {
                let out = history::branch(repo, name)?;
                if let Some(recorded) = recorded_change(e) {
                    self.changes.insert(recorded, out.change);
                }
            }
            Op::Merge { other } => {
                let other = self.change(*other);
                let out = merge::merge(repo, &other.to_string())?;
                if let Some(recorded) = recorded_change(e) {
                    self.changes.insert(recorded, out.change);
                }
            }
            // Undo and restore both set a recorded view; restore the mapped ids.
            Op::Undo | Op::Restore { .. } => {
                let mut view = repo.view()?;
                if let Some(root) = self.snaps.get(&e.after.root) {
                    view.root = *root;
                }
                for (change, snap) in &e.after.heads {
                    if let Some(mapped) = self.snaps.get(snap) {
                        view.heads.insert(self.change(*change), *mapped);
                    }
                }
                repo.restore_view(&view, e.op.clone())?;
            }
            Op::Resolve { conflict, take } => {
                merge::resolve(repo, *conflict as usize, *take)?;
            }
            Op::Absorb => {
                write_changes(repo.root_dir(), &b.files)?;
                repo.absorb()?;
            }
            Op::Note { to, kind, text } => {
                let to = match to {
                    NoteTo::Entity(id) => NoteTo::Entity(self.entity(&cur, b, *id)?),
                    other => other.clone(),
                };
                repo.mutate(
                    Op::Note {
                        to,
                        kind: kind.clone(),
                        text: text.clone(),
                    },
                    e.observed,
                    |_, cur| Ok(cur.id()),
                )?;
            }
        }
        Ok(())
    }
}

/// The change an op minted: the head that is the op's after root.
fn recorded_change(e: &OpLogEntry) -> Option<ChangeId> {
    e.after.heads.iter().find(|(_, s)| **s == e.after.root).map(|(c, _)| *c)
}

fn write_changes(root: &std::path::Path, files: &BTreeMap<RelPath, FileBody>) -> Result<()> {
    for (path, body) in files {
        let at = root.join(path.as_str());
        match body {
            FileBody::Removed => {
                let _ = std::fs::remove_file(&at);
            }
            FileBody::Text(t) => write_file(&at, t.as_bytes())?,
            FileBody::Bytes(v) => write_file(&at, v)?,
        }
    }
    Ok(())
}

fn write_file(at: &std::path::Path, bytes: &[u8]) -> Result<()> {
    if let Some(dir) = at.parent() {
        std::fs::create_dir_all(dir).map_err(Error::backend)?;
    }
    std::fs::write(at, bytes).map_err(Error::backend)
}

/// Replay `bundle` into `repo`, whose current tree must be the bundle's base. Stops at the
/// first entry that cannot be applied; reports the first whose result differs from the record.
pub fn import(repo: &Repo, bundle: &Bundle) -> Result<ImportReport> {
    let have = tree_hash(&rendered(repo, &repo.current()?)?);
    if have != bundle.base_tree {
        return Err(Error::Other(format!(
            "this tree is not the bundle's base (tree {}…, bundle starts from {}…)",
            &have[..12],
            &bundle.base_tree[..12]
        )));
    }
    for cs in &bundle.changesets {
        match repo.store().get_changeset(cs.id) {
            Ok(mut have) => {
                // The row this side holds keeps what it has (its own queue entries); the
                // sender's additions join it.
                let mut grew = false;
                for item in &cs.queue {
                    if !have.queue.contains(item) {
                        have.queue.push(item.clone());
                        grew = true;
                    }
                }
                if have.description.is_empty() && !cs.description.is_empty() {
                    have.description = cs.description.clone();
                    grew = true;
                }
                if grew {
                    repo.store().put_changeset(&have)?;
                }
            }
            Err(_) => repo.store().put_changeset(cs)?,
        }
    }
    let mut im = Import { repo, changes: BTreeMap::new(), snaps: BTreeMap::new(), from_record: Vec::new() };
    if let Some(first) = bundle.entries.first() {
        im.snaps.insert(first.entry.before.root, repo.store().root()?);
    }
    let mut diverged_at = None;
    let mut applied = 0;
    for b in &bundle.entries {
        // The op line keeps its recorded time, changeset and checkout.
        let p = Provenance { at: b.entry.at, group: b.entry.group, workspace: b.workspace.clone() };
        repo.with_provenance(p, || im.apply(b))?;
        applied += 1;
        im.snaps.insert(b.entry.after.root, repo.store().root()?);
        if diverged_at.is_none() {
            let got = tree_hash(&rendered(repo, &repo.current()?)?);
            if got != b.after_tree {
                diverged_at = Some(b.ix);
            }
        }
    }
    Ok(ImportReport { applied, from_record: im.from_record, diverged_at })
}

crates/svc-repo/src/replay.rs.Text:
//! O5 (the oracle set): replaying the op log from the root reproduces every snapshot. The replay
//! runs on a fresh store with no filesystem, so anything the verbs keep outside the op path
//! shows up as a divergence. Snapshot hashes include change ids, and `Branch`/`Merge` mint
//! theirs at run time, so equality is on **content** (`Snapshot::content_eq`) with ids mapped
//! as the replay goes.

use std::collections::BTreeMap;

use serde::Serialize;
use svc_core::engine::{add_def_at, delete, edit_def, inline, move_def, relocate, rename};
use svc_core::{
    ChangeId, Langs, MemStore, Op, OpIx, OpLogEntry, Result, Snapshot, SnapshotId, Store, View,
};

use crate::history::child_of;
use crate::merge::{lca, merged_snapshot};
use crate::repo::Repo;

#[derive(Clone, Debug, Serialize)]
pub struct ReplayReport {
    pub ops: usize,
    /// First op whose replayed result differs from the recorded `after.root`, if any.
    pub diverged_at: Option<OpIx>,
}

impl ReplayReport {
    pub fn ok(&self) -> bool {
        self.diverged_at.is_none()
    }
}

struct Replay<'a> {
    src: &'a dyn Store,
    store: MemStore,
    langs: &'a Langs,
    /// Recorded snapshot id → replayed snapshot id.
    snaps: BTreeMap<SnapshotId, SnapshotId>,
    changes: BTreeMap<ChangeId, ChangeId>,
}

impl Replay<'_> {
    fn change(&self, c: ChangeId) -> ChangeId {
        *self.changes.get(&c).unwrap_or(&c)
    }

    fn current(&self) -> Result<Snapshot> {
        self.store.get_snapshot(self.store.root()?)
    }

    fn commit(&self, snap: &Snapshot) -> Result<SnapshotId> {
        let id = self.store.put_snapshot(snap)?;
        self.store.set_head(snap.change, id)?;
        self.store.set_root(id)?;
        Ok(id)
    }

    fn amend(&self, cur: &Snapshot, mut next: Snapshot) -> Result<SnapshotId> {
        let cur_id = cur.id();
        if next.content_eq(cur) {
            return Ok(cur_id);
        }
        next.parents = cur.parents.clone();
        next.predecessors = vec![cur_id];
        next.change = cur.change;
        self.commit(&next)
    }

    /// Copy a recorded snapshot in (used for `Absorb`, whose result is data, not an op).
    fn import(&mut self, recorded: SnapshotId) -> Result<SnapshotId> {
        let mut snap = self.src.get_snapshot(recorded)?;
        snap.change = self.change(snap.change);
        snap.parents = snap.parents.iter().map(|p| *self.snaps.get(p).unwrap_or(p)).collect();
        snap.predecessors = snap.predecessors.iter().map(|p| *self.snaps.get(p).unwrap_or(p)).collect();
        for rec in snap.entities.values() {
            self.store.put_blob(&self.src.get_blob(&rec.content.0)?)?;
            self.store.put_blob(&self.src.get_blob(&rec.bytes.0)?)?;
        }
        self.commit(&snap)
    }

    fn restore(&self, view: &View) -> Result<()> {
        for (change, snap) in &view.heads {
            if let Some(mapped) = self.snaps.get(snap) {
                self.store.set_head(self.change(*change), *mapped)?;
            }
        }
        if let Some(root) = self.snaps.get(&view.root) {
            self.store.set_root(*root)?;
        }
        Ok(())
    }

    fn apply(&mut self, e: &OpLogEntry) -> Result<()> {
        // The entry records which root it started from. With several checkouts on one op
        // log (or a `checkout` between ops) that is not necessarily the last op's result:
        // switch to it first — a checkout switch, not a content change.
        if let Some(mapped) = self.snaps.get(&e.before.root).copied() {
            if mapped != self.store.root()? {
                self.store.set_root(mapped)?;
            }
        }
        let cur = self.current()?;
        match &e.op {
            Op::Rename { id, new } => {
                self.amend(&cur, rename(&self.store, &cur, *id, new)?)?;
            }
            Op::Move { id, parent, ordinal } => {
                self.amend(&cur, move_def(&self.store, self.langs, &cur, *id, *parent, *ordinal)?)?;
            }
            Op::Relocate { id, file, ordinal } => {
                self.amend(&cur, relocate(&cur, &self.store, *id, file.clone(), *ordinal)?)?;
            }
            Op::Extract { id, new_parent, ordinal } => {
                self.amend(&cur, move_def(&self.store, self.langs, &cur, *id, *new_parent, Some(*ordinal))?)?;
            }
            Op::Inline { id } => {
                self.amend(&cur, inline(&self.store, self.langs, &cur, *id)?)?;
            }
            Op::AddDef { id, parent, ordinal, definition, intent, file } => {
                let next = add_def_at(&self.store, self.langs, &cur, *id, *parent, file.clone(), *ordinal, definition.as_bytes(), intent.clone())?;
                self.amend(&cur, next)?;
            }
            Op::Delete { id, .. } => {
                self.amend(&cur, delete(&cur, &self.store, *id)?)?;
            }
            Op::EditDef { id, definition, .. } => {
                let (next, _) = edit_def(&self.store, self.langs, &cur, *id, definition.as_bytes())?;
                self.amend(&cur, next)?;
            }
            Op::New { change } => {
                let c = self.change(*change);
                self.commit(&child_of(&cur, cur.id(), c))?;
            }
            Op::Describe { msg } => {
                let mut next = cur.clone();
                next.message = msg.clone();
                self.amend(&cur, next)?;
            }
            Op::Branch { .. } => {
                let recorded = self.src.get_snapshot(e.after.root)?;
                let c = self.fresh_change(recorded.change);
                let (base, base_id) = match cur.parents.first() {
                    Some(p) => (self.store.get_snapshot(*p)?, *p),
                    None => (cur.clone(), cur.id()),
                };
                self.commit(&child_of(&base, base_id, c))?;
            }
            Op::Merge { other } => {
                let other_id = self.store.head(self.change(*other))?;
                let cur_id = cur.id();
                let base_id = lca(&self.store, cur_id, other_id)?
                    .ok_or_else(|| svc_core::Error::Other("replay: no common ancestor".into()))?;
                let recorded = self.src.get_snapshot(e.after.root)?;
                let c = self.fresh_change(recorded.change);
                let snap = merged_snapshot(&self.store, self.langs, base_id, cur_id, other_id, c)?;
                self.commit(&snap)?;
            }
            Op::Undo | Op::Restore { .. } => self.restore(&e.after)?,
            Op::Resolve { conflict, take } => {
                let (next, _) = crate::merge::resolved_snapshot(&self.store, &cur, *conflict as usize, *take)?;
                self.amend(&cur, next)?;
            }
            Op::Absorb => {
                self.import(e.after.root)?;
            }
            Op::Note { .. } => {}
        }
        Ok(())
    }

    fn fresh_change(&mut self, recorded: ChangeId) -> ChangeId {
        let c = ChangeId::new();
        self.changes.insert(recorded, c);
        c
    }
}

/// Replay `repo`'s op log on a fresh store; report the first divergence.
pub fn replay(repo: &Repo) -> Result<ReplayReport> {
    let src = repo.store();
    let ops = src.ops(OpIx(0), false)?;
    let mut r = Replay {
        src,
        store: MemStore::new(),
        langs: repo.langs(),
        snaps: BTreeMap::new(),
        changes: BTreeMap::new(),
    };
    let mut diverged_at = None;
    for (i, (ix, e)) in ops.iter().enumerate() {
        if i == 0 {
            // The init op's `after.root` is the ingested tree; replay starts from it.
            r.import(e.after.root)?;
        } else {
            r.apply(e)?;
        }
        let got = r.current()?;
        let want = src.get_snapshot(e.after.root)?;
        r.snaps.insert(e.after.root, got.id());
        if !got.content_eq(&want) && diverged_at.is_none() {
            diverged_at = Some(*ix);
        }
    }
    Ok(ReplayReport {
        ops: ops.len(),
        diverged_at,
    })
}

crates/svc-repo/tests/bundle.rs.Text:
//! A store's op log, exported as a bundle and replayed into a fresh store over the same
//! tree, reproduces every tree the log records — through renames, a typed edit, a hand
//! edit, a branch, a conflicting merge, its resolution and an undo — and the replayed
//! store answers svc's questions about real entities.

use std::path::Path;

use svc_core::engine::{classify_def, edit_def, rename};
use svc_core::{Op, OpIx, Take};
use svc_repo::bundle::{self, Bundle};
use svc_repo::{Repo, workspace};

const HERE: &str = env!("CARGO_MANIFEST_DIR");

fn demo_crate(into: &Path) {
    let src = Path::new(HERE).join("../../demo/config");
    for name in ["Cargo.toml", "config.txt"] {
        std::fs::copy(src.join(name), into.join(name)).unwrap();
    }
    std::fs::create_dir_all(into.join("src")).unwrap();
    std::fs::copy(src.join("src/main.rs"), into.join("src/main.rs")).unwrap();
}

fn rename_to(repo: &Repo, from: &str, to: &str) {
    let id = svc_repo::resolve_entity(repo, from).unwrap();
    repo.mutate(Op::Rename { id, new: to.into() }, None, |repo, cur| repo.amend(cur, rename(repo.store(), cur, id, to)?))
        .unwrap();
}

fn edit(repo: &Repo, entity: &str, definition: &str) {
    let id = svc_repo::resolve_entity(repo, entity).unwrap();
    let cur = repo.current().unwrap();
    let observed = classify_def(repo.store(), repo.langs(), &cur, id, definition.as_bytes()).unwrap();
    let op = Op::EditDef { id, definition: definition.into(), intent: svc_core::Intent::Refactor };
    repo.mutate(op, Some(observed), |repo, cur| {
        let (next, _) = edit_def(repo.store(), repo.langs(), cur, id, definition.as_bytes())?;
        repo.amend(cur, next)
    })
    .unwrap();
}

#[test]
fn a_bundle_replays_the_whole_story_into_a_fresh_store_over_the_same_tree() {
    let a = tempfile::tempdir().unwrap();
    demo_crate(a.path());
    let repo = Repo::init(a.path(), Repo::default_langs()).unwrap();
    svc_repo::new(&repo).unwrap();
    svc_repo::changeset_begin(&repo, "the agent run", svc_core::Intent::Refactor, None, false).unwrap();
    rename_to(&repo, "parse", "parse_config");
    edit(&repo, "normalize", "fn normalize(s: &str) -> String {\n    s.trim().to_lowercase()\n}");
    svc_repo::changeset_end(&repo).unwrap();
    // A hand edit to an opaque file, absorbed.
    std::fs::write(a.path().join("config.txt"), "hand-edited\n").unwrap();
    svc_repo::status(&repo).unwrap();
    // A second line of work on the same entity, merged back with a conflict.
    let trunk = repo.current_change().unwrap();
    svc_repo::branch(&repo, "side").unwrap();
    edit(&repo, "normalize", "fn normalize(s: &str) -> String {\n    s.trim().to_uppercase()\n}");
    let side = repo.current_change().unwrap();
    svc_repo::checkout(&repo, repo.store().head(trunk).unwrap()).unwrap();
    let m = svc_repo::merge(&repo, &side.to_string()).unwrap();
    assert_eq!(m.conflicts.len(), 1, "{:?}", m.conflicts);
    svc_repo::resolve(&repo, 0, Take::B).unwrap();
    rename_to(&repo, "load", "load_config");
    let renamed_at = svc_repo::op_log(&repo).unwrap()[0].ix;
    svc_repo::undo(&repo).unwrap();
    svc_repo::op_restore(&repo, renamed_at).unwrap(); // a redo: logged as Undo, like the undo
    let recorded = svc_repo::op_log(&repo).unwrap().len();

    let bundle = bundle::export(&repo, OpIx(1)).unwrap();
    assert_eq!(bundle.entries.len(), recorded - 1, "everything after init");
    let text = serde_json::to_string(&bundle).unwrap();
    assert!(text.contains("hand-edited"), "the absorbed file travels with its op");
    let bundle: Bundle = serde_json::from_str(&text).unwrap();

    // A fresh store over the same bytes: every entity has a new id; the paths match.
    let b = tempfile::tempdir().unwrap();
    demo_crate(b.path());
    let fresh = Repo::init(b.path(), Repo::default_langs()).unwrap();
    let report = bundle::import(&fresh, &bundle).unwrap();
    assert_eq!(report.applied, bundle.entries.len());
    assert_eq!(report.diverged_at, None, "every tree after every op is the recorded one");

    let text = std::fs::read_to_string(b.path().join("src/main.rs")).unwrap();
    assert!(text.contains("fn parse_config(") && text.contains("to_uppercase") && text.contains("fn load_config("), "{text}");
    assert_eq!(std::fs::read_to_string(b.path().join("config.txt")).unwrap(), "hand-edited\n");
    let log = svc_repo::op_log(&fresh).unwrap();
    assert_eq!(log.len(), recorded, "same number of ops, init included");
    let kinds: Vec<String> = log.iter().rev().map(|o| format!("{:?}", o.op).split(' ').next().unwrap().trim_end_matches('{').to_string()).collect();
    let recorded_kinds: Vec<String> = svc_repo::op_log(&repo).unwrap().iter().rev().map(|o| format!("{:?}", o.op).split(' ').next().unwrap().trim_end_matches('{').to_string()).collect();
    assert_eq!(kinds, recorded_kinds);
    // The replayed lines keep their recorded times and changesets, not the import's — and the
    // changeset rows travel too, so a group keeps its name.
    let recorded_log = svc_repo::op_log(&repo).unwrap();
    for (got, want) in log.iter().zip(recorded_log.iter()).filter(|(_, w)| w.ix.0 > 0) {
        assert_eq!(got.at, want.at, "op {} keeps its time", want.ix.0);
        assert_eq!(got.group, want.group, "op {} keeps its changeset", want.ix.0);
    }
    let named: Vec<String> = svc_repo::changesets(&fresh).unwrap().into_iter().map(|c| c.name).collect();
    assert!(named.contains(&"the agent run".to_string()), "the changeset row travelled: {named:?}");
    let id = svc_repo::resolve_entity(&fresh, "normalize").unwrap();
    let blame = svc_repo::blame(&fresh, id).unwrap();
    assert!(blame.len() >= 3, "added, edited, merged/resolved: {blame:?}");
    assert!(svc_repo::replay(&fresh).unwrap().ok());
    assert!(!workspace::list(&fresh).unwrap()[0].stale);
}

#[test]
fn import_refuses_a_tree_that_is_not_the_bundles_base() {
    let a = tempfile::tempdir().unwrap();
    demo_crate(a.path());
    let repo = Repo::init(a.path(), Repo::default_langs()).unwrap();
    rename_to(&repo, "parse", "parse_config");
    let bundle = bundle::export(&repo, OpIx(1)).unwrap();

    let b = tempfile::tempdir().unwrap();
    demo_crate(b.path());
    std::fs::write(b.path().join("config.txt"), "different base\n").unwrap();
    let other = Repo::init(b.path(), Repo::default_langs()).unwrap();
    let err = bundle::import(&other, &bundle).err().expect("refused");
    assert!(err.to_string().contains("not the bundle's base"), "{err}");
}

#[test]
fn when_the_engine_no_longer_computes_the_recorded_tree_the_record_supplies_it() {
    let a = tempfile::tempdir().unwrap();
    demo_crate(a.path());
    let repo = Repo::init(a.path(), Repo::default_langs()).unwrap();
    rename_to(&repo, "parse", "parse_config");
    edit(&repo, "normalize", "fn normalize(s: &str) -> String {\n    s.trim().to_lowercase()\n}");
    let mut bundle = bundle::export(&repo, OpIx(1)).unwrap();
    // Every typed op carries the files it changed, not only absorbs.
    assert!(bundle.entries.iter().all(|b| !b.files.is_empty()), "files on every op");
    // Stand in for an engine that has changed since: the edit's definition is tampered with,
    // so what the engine computes no longer matches the recorded tree.
    let edited = bundle.entries.iter().position(|b| matches!(b.entry.op, Op::EditDef { .. })).unwrap();
    if let Op::EditDef { definition, .. } = &mut bundle.entries[edited].entry.op {
        *definition = "fn normalize(s: &str) -> String {\n    s.to_string()\n}".into();
    }
    let ix = bundle.entries[edited].ix;

    let b = tempfile::tempdir().unwrap();
    demo_crate(b.path());
    let fresh = Repo::init(b.path(), Repo::default_langs()).unwrap();
    let report = bundle::import(&fresh, &bundle).unwrap();
    assert_eq!(report.from_record, vec![ix], "that one op came from the record");
    assert_eq!(report.diverged_at, None, "and the tree is the recorded one");
    let text = std::fs::read_to_string(b.path().join("src/main.rs")).unwrap();
    assert!(text.contains("to_lowercase") && !text.contains("s.to_string()"), "{text}");
    assert_eq!(svc_repo::op_log(&fresh).unwrap().len(), 3, "still one op per recorded op");
}

crates/svc-repo/tests/merge.rs.Text:
//! Acceptance tests for `svc merge`: the verbs are svc-repo's, the algorithm is
//! `svc_core::engine::merge`. Fixtures go through the real ops so the merged snapshot is
//! something the binding post-condition can render and re-parse.

use svc_core::engine::{add_def, delete, edit_def, rename};
use svc_core::{Conflict, EntityId, Intent, Op};
use svc_repo::{Repo, Take};

const LIB: &str = "struct Config { path: String }\n\nfn read(path: &str) -> String {\n    path.to_string()\n}\n\nfn helper_base() {}\n\nfn main() {\n    let _ = read(\"x\");\n}\n";

fn fresh() -> (tempfile::TempDir, Repo) {
    let dir = tempfile::tempdir().unwrap();
    std::fs::create_dir_all(dir.path().join("src")).unwrap();
    std::fs::write(dir.path().join("src/lib.rs"), LIB).unwrap();
    let repo = Repo::init(dir.path(), Repo::default_langs()).unwrap();
    svc_repo::new(&repo).unwrap();
    (dir, repo)
}

fn entity(repo: &Repo, name: &str) -> EntityId {
    svc_repo::resolve_entity(repo, name).unwrap()
}

fn rename_op(repo: &Repo, id: EntityId, new: &str) {
    repo.mutate(Op::Rename { id, new: new.into() }, None, |repo, cur| {
        repo.amend(cur, rename(repo.store(), cur, id, new)?)
    })
    .unwrap();
}

fn edit(repo: &Repo, id: EntityId, definition: &str) {
    repo.mutate(
        Op::EditDef { id, definition: definition.into(), intent: Intent::Feature },
        None,
        |repo, cur| {
            let (next, _) = edit_def(repo.store(), repo.langs(), cur, id, definition.as_bytes())?;
            repo.amend(cur, next)
        },
    )
    .unwrap();
}

fn add(repo: &Repo, definition: &str) -> EntityId {
    let id = EntityId::new();
    let ordinal = repo.current().unwrap().entities.len() as u32;
    repo.mutate(
        Op::AddDef { id, parent: None, ordinal, definition: definition.into(), intent: Intent::Feature, file: None },
        None,
        |repo, cur| {
            let next = add_def(repo.store(), repo.langs(), cur, id, None, ordinal, definition.as_bytes(), Intent::Feature)?;
            repo.amend(cur, next)
        },
    )
    .unwrap();
    id
}

fn text(dir: &tempfile::TempDir) -> String {
    std::fs::read_to_string(dir.path().join("src/lib.rs")).unwrap()
}

#[test]
fn demo_line_5_rename_on_a_edit_on_b_merges_clean() {
    let (dir, repo) = fresh();
    let read = entity(&repo, "read");
    let main = entity(&repo, "main");
    svc_repo::branch(&repo, "a").unwrap();
    rename_op(&repo, read, "read_file");
    svc_repo::branch(&repo, "b").unwrap();
    assert_eq!(repo.current().unwrap().entities[&read].name, "read", "b is a sibling of a");
    edit(&repo, main, "fn main() {\n    let _ = read(\"x\");\n    let _ = read(\"y\");\n}\n");

    let out = svc_repo::merge(&repo, "a").unwrap();
    assert!(out.conflicts.is_empty(), "{:?}", out.conflicts);
    let snap = repo.current().unwrap();
    assert_eq!(snap.change, out.change);
    assert_eq!(snap.parents.len(), 2);
    assert_eq!(snap.entities[&read].name, "read_file");
    let t = text(&dir);
    assert!(t.contains("fn read_file(path"), "{t}");
    assert!(t.contains("read_file(\"y\")"), "B's new call renders A's name: {t}");
    assert!(!t.contains("read(\""), "{t}");
    assert!(repo.working_copy_clean().unwrap());
    let log = svc_repo::log(&repo, None).unwrap();
    assert!(matches!(log[0].op, Op::Merge { .. }));
}

#[test]
fn rename_rename_is_an_attr_conflict_resolved_by_take() {
    let (_dir, repo) = fresh();
    let read = entity(&repo, "read");
    svc_repo::branch(&repo, "a").unwrap();
    rename_op(&repo, read, "load");
    svc_repo::branch(&repo, "b").unwrap();
    rename_op(&repo, read, "fetch");
    let out = svc_repo::merge(&repo, "a").unwrap();
    let attrs: Vec<_> = out.conflicts.iter().filter(|c| matches!(c.conflict, Conflict::Attr { .. })).collect();
    assert_eq!(attrs.len(), 1, "{:?}", out.conflicts);
    assert_eq!(out.conflicts.len(), 1, "no other conflicts: {:?}", out.conflicts);
    let n = attrs[0].n;

    let resolved = svc_repo::resolve(&repo, n, Take::B).unwrap();
    assert!(resolved.conflicts.is_empty(), "{:?}", resolved.conflicts);
    assert_eq!(repo.current().unwrap().entities[&read].name, "load");
    assert_eq!(repo.current().unwrap().change, out.change, "resolve amends the merge change");
    assert!(svc_repo::resolve(&repo, n, Take::A).is_err());
}

#[test]
fn delete_edit_conflict_keeps_the_edit() {
    let (_dir, repo) = fresh();
    let helper = entity(&repo, "helper_base");
    svc_repo::branch(&repo, "a").unwrap();
    repo.mutate(Op::Delete { id: helper, intent: Intent::Refactor }, None, |repo, cur| {
        repo.amend(cur, delete(cur, repo.store(), helper)?)
    })
    .unwrap();
    svc_repo::branch(&repo, "b").unwrap();
    edit(&repo, helper, "fn helper_base() { let _ = 1; }\n");
    let out = svc_repo::merge(&repo, "a").unwrap();
    let de: Vec<_> = out.conflicts.iter().filter(|c| matches!(c.conflict, Conflict::DeleteEdit { .. })).collect();
    assert_eq!(de.len(), 1, "{:?}", out.conflicts);
    assert!(repo.current().unwrap().entities.contains_key(&helper));
    svc_repo::resolve(&repo, de[0].n, Take::B).unwrap();
    assert!(!repo.current().unwrap().entities.contains_key(&helper), "take B = the merged-in branch's delete");
}

#[test]
fn both_edit_same_body_differently_is_a_content_conflict() {
    let (_dir, repo) = fresh();
    let main = entity(&repo, "main");
    svc_repo::branch(&repo, "a").unwrap();
    edit(&repo, main, "fn main() {\n    let a = 1;\n    let _ = a;\n}\n");
    svc_repo::branch(&repo, "b").unwrap();
    edit(&repo, main, "fn main() {\n    let b = 2;\n    let _ = b;\n}\n");
    let out = svc_repo::merge(&repo, "a").unwrap();
    let content: Vec<_> = out.conflicts.iter().filter(|c| matches!(c.conflict, Conflict::Content { .. })).collect();
    assert_eq!(content.len(), 1, "{:?}", out.conflicts);
    svc_repo::resolve(&repo, content[0].n, Take::Base).unwrap();
    let cur = repo.current().unwrap();
    assert!(cur.conflicts.iter().all(|c| !matches!(c, Conflict::Content { .. })));
    let base = repo.store().get_snapshot(out.base).unwrap();
    assert_eq!(cur.entities[&main].content, base.entities[&main].content);
}

#[test]
fn both_edit_same_body_disjointly_merges_clean() {
    let (dir, repo) = fresh();
    let main = entity(&repo, "main");
    edit(&repo, main, "fn main() {\n    let _ = read(\"x\");\n    let one = 1;\n    let two = 2;\n    let three = 3;\n    let _ = (one, two, three);\n}\n");
    svc_repo::new(&repo).unwrap();
    svc_repo::branch(&repo, "a").unwrap();
    edit(&repo, main, "fn main() {\n    let _ = read(\"x\");\n    let one = 10;\n    let two = 2;\n    let three = 3;\n    let _ = (one, two, three);\n}\n");
    svc_repo::branch(&repo, "b").unwrap();
    edit(&repo, main, "fn main() {\n    let _ = read(\"x\");\n    let one = 1;\n    let two = 2;\n    let three = 30;\n    let _ = (one, two, three);\n}\n");
    let out = svc_repo::merge(&repo, "a").unwrap();
    assert!(out.conflicts.is_empty(), "{:?}", out.conflicts);
    let t = text(&dir);
    assert!(t.contains("let one = 10;") && t.contains("let three = 30;"), "{t}");
}

#[test]
fn add_add_same_signature_unifies_and_rewrites_references() {
    let (dir, repo) = fresh();
    let main = entity(&repo, "main");
    svc_repo::branch(&repo, "a").unwrap();
    let helper_a = add(&repo, "fn helper() -> u8 { 1 }\n");
    svc_repo::branch(&repo, "b").unwrap();
    let helper_b = add(&repo, "fn helper() -> u8 { 1 }\n");
    edit(&repo, main, "fn main() {\n    let _ = read(\"x\");\n    let _ = helper();\n}\n");

    let out = svc_repo::merge(&repo, "a").unwrap();
    assert!(out.conflicts.is_empty(), "{:?}", out.conflicts);
    let snap = repo.current().unwrap();
    assert_eq!(snap.entities.values().filter(|r| r.name == "helper").count(), 1);
    let survivor = snap.entities.keys().find(|id| **id == helper_a || **id == helper_b).copied().unwrap();
    let bytes = repo.store().get_bytes_blob(snap.entities[&main].bytes).unwrap();
    assert!(bytes.chunks().contains(&svc_core::Chunk::Name(survivor)), "main's call points at the surviving id");
    let t = text(&dir);
    assert_eq!(t.matches("fn helper()").count(), 1, "{t}");
    assert!(t.contains("let _ = helper();"), "{t}");
}

#[test]
fn merge_of_an_ancestor_is_refused_and_ordinals_stay_dense() {
    let (_dir, repo) = fresh();
    svc_repo::branch(&repo, "a").unwrap();
    svc_repo::branch(&repo, "b").unwrap();
    assert!(svc_repo::merge(&repo, "nope").is_err());
    add(&repo, "fn extra_b() {}\n");
    svc_repo::edit(&repo, "a").unwrap();
    add(&repo, "fn extra_a() {}\n");
    let out = svc_repo::merge(&repo, "b").unwrap();
    assert!(out.conflicts.is_empty(), "{:?}", out.conflicts);
    let snap = repo.current().unwrap();
    let mut ords: Vec<u32> = snap.entities.values().map(|r| r.ordinal).collect();
    ords.sort();
    assert_eq!(ords, (0..snap.entities.len() as u32).collect::<Vec<_>>());
    assert!(svc_repo::merge(&repo, "b").is_err(), "already an ancestor");
}

crates/svc-repo/tests/o5_replay.rs.Text:
//! O5: replaying the op log on a fresh store reproduces every snapshot's content.

use svc_core::engine::{add_def, edit_def, rename};
use svc_core::{EntityId, Intent, Op};
use svc_repo::Repo;

const LIB: &str = "struct Config { path: String }\n\nfn read(path: &str) -> String {\n    path.to_string()\n}\n\nfn helper_base() {}\n\nfn main() {\n    let _ = read(\"x\");\n}\n";

fn fresh() -> (tempfile::TempDir, Repo) {
    let dir = tempfile::tempdir().unwrap();
    std::fs::create_dir_all(dir.path().join("src")).unwrap();
    std::fs::write(dir.path().join("src/lib.rs"), LIB).unwrap();
    let repo = Repo::init(dir.path(), Repo::default_langs()).unwrap();
    (dir, repo)
}

fn rename_op(repo: &Repo, name: &str, new: &str) {
    let id = svc_repo::resolve_entity(repo, name).unwrap();
    repo.mutate(Op::Rename { id, new: new.into() }, None, |repo, cur| repo.amend(cur, rename(repo.store(), cur, id, new)?))
        .unwrap();
}

fn edit(repo: &Repo, name: &str, definition: &str) {
    let id = svc_repo::resolve_entity(repo, name).unwrap();
    repo.mutate(
        Op::EditDef { id, definition: definition.into(), intent: Intent::Feature },
        None,
        |repo, cur| {
            let (next, _) = edit_def(repo.store(), repo.langs(), cur, id, definition.as_bytes())?;
            repo.amend(cur, next)
        },
    )
    .unwrap();
}

fn add(repo: &Repo, definition: &str) {
    let id = EntityId::new();
    let ordinal = repo.current().unwrap().entities.len() as u32;
    repo.mutate(
        Op::AddDef { id, parent: None, ordinal, definition: definition.into(), intent: Intent::Feature, file: None },
        None,
        |repo, cur| {
            let next = add_def(repo.store(), repo.langs(), cur, id, None, ordinal, definition.as_bytes(), Intent::Feature)?;
            repo.amend(cur, next)
        },
    )
    .unwrap();
}

#[test]
fn o5_replay_reproduces_every_snapshot() {
    let (dir, repo) = fresh();
    svc_repo::new(&repo).unwrap();
    rename_op(&repo, "read", "read_file");
    svc_repo::describe(&repo, "rename read").unwrap();
    edit(&repo, "main", "fn main() {\n    let _ = read_file(\"y\");\n}\n");
    // A hand edit, absorbed by the next op.
    std::fs::write(
        dir.path().join("src/lib.rs"),
        std::fs::read_to_string(dir.path().join("src/lib.rs")).unwrap().replace("fn helper_base() {}", "fn helper_base() { let _ = 0; }"),
    )
    .unwrap();
    svc_repo::status(&repo).unwrap();
    svc_repo::new(&repo).unwrap();
    svc_repo::branch(&repo, "a").unwrap();
    add(&repo, "fn from_a() {}\n");
    svc_repo::branch(&repo, "b").unwrap();
    add(&repo, "fn from_b() {}\n");
    svc_repo::merge(&repo, "a").unwrap();
    svc_repo::undo(&repo).unwrap();
    svc_repo::undo(&repo).unwrap();

    let report = svc_repo::replay(&repo).unwrap();
    assert!(report.ops >= 12, "{report:?}");
    assert!(report.ok(), "replay diverged: {report:?}");
}

/// two checkouts share one op log but start ops from different roots. Two
/// changes edited alternately look the same to the log (`edit` switches root without an
/// entry), so [A: rename] [B: rename] [A: describe] must replay by following each entry's
/// recorded `before.root`, not the last op's result.
#[test]
fn o5_follows_each_ops_recorded_root_across_checkouts() {
    let (_dir, repo) = fresh();
    svc_repo::new(&repo).unwrap();
    let a = repo.current_change().unwrap();
    rename_op(&repo, "read", "read_file"); // A
    svc_repo::branch(&repo, "b").unwrap(); // B: a sibling change, now current
    rename_op(&repo, "helper_base", "helper"); // B, from B's root
    svc_repo::edit(&repo, &a.to_string()).unwrap(); // back to A's head: a root switch, no op
    svc_repo::describe(&repo, "renamed read").unwrap(); // A, from A's root

    let report = svc_repo::replay(&repo).unwrap();
    assert_eq!(report.ops, 6, "init, new, rename, branch, rename, describe");
    assert!(report.ok(), "diverged at {:?}", report.diverged_at);
}

crates/svc-repo/tests/sync.rs.Text:
//! A changeset moves between two clones with its review state: after `transfer`, the
//! receiving store lists the group's ops with the same verdicts, subjects and times; a
//! second transfer sends nothing; a later op joins the same group and travels alone; the
//! other clone's own addition comes back the same way.

use std::path::Path;

use svc_core::engine::{classify_def, edit_def, rename};
use svc_core::{Intent, Op};
use svc_repo::sync::transfer;
use svc_repo::{Repo, changeset_begin, changeset_end, changeset_reopen, changesets, resolve_changeset};

const HERE: &str = env!("CARGO_MANIFEST_DIR");

fn demo_crate(into: &Path) {
    let src = Path::new(HERE).join("../../demo/config");
    for name in ["Cargo.toml", "config.txt"] {
        std::fs::copy(src.join(name), into.join(name)).unwrap();
    }
    std::fs::create_dir_all(into.join("src")).unwrap();
    std::fs::copy(src.join("src/main.rs"), into.join("src/main.rs")).unwrap();
}

fn rename_to(repo: &Repo, from: &str, to: &str) {
    let id = svc_repo::resolve_entity(repo, from).unwrap();
    repo.mutate(Op::Rename { id, new: to.into() }, None, |repo, cur| repo.amend(cur, rename(repo.store(), cur, id, to)?))
        .unwrap();
}

fn edit(repo: &Repo, entity: &str, definition: &str) {
    let id = svc_repo::resolve_entity(repo, entity).unwrap();
    let cur = repo.current().unwrap();
    let observed = classify_def(repo.store(), repo.langs(), &cur, id, definition.as_bytes()).unwrap();
    let op = Op::EditDef { id, definition: definition.into(), intent: Intent::Refactor };
    repo.mutate(op, Some(observed), |repo, cur| {
        let (next, _) = edit_def(repo.store(), repo.langs(), cur, id, definition.as_bytes())?;
        repo.amend(cur, next)
    })
    .unwrap();
}

/// What both clones must agree on: everything about the group's ops except the op index
/// (each clone's own log position) and the entity id (each clone's own, mapped by path).
fn review_state(repo: &Repo, name: &str) -> Vec<String> {
    let cs = changesets(repo).unwrap().into_iter().find(|c| c.name == name).unwrap();
    cs.ops
        .iter()
        .map(|o| {
            let kind = match o.op {
                Op::Rename { .. } => "rename",
                Op::EditDef { .. } => "edit-def",
                _ => "other",
            };
            format!(
                "{kind} {:?} {:?} {} {:?} {}",
                o.declared,
                o.observed,
                o.flagged,
                o.subject,
                o.at
            )
        })
        .collect()
}

#[test]
fn a_changeset_travels_with_its_review_state_and_only_what_is_new_travels() {
    let (a_dir, b_dir) = (tempfile::tempdir().unwrap(), tempfile::tempdir().unwrap());
    demo_crate(a_dir.path());
    demo_crate(b_dir.path());
    let a = Repo::init(a_dir.path(), Repo::default_langs()).unwrap();
    let b = Repo::init(b_dir.path(), Repo::default_langs()).unwrap();

    let cs = changeset_begin(&a, "reviewed", Intent::Refactor, None, false).unwrap().id;
    rename_to(&a, "read", "read_file");
    edit(&a, "normalize", "fn normalize(s: &str) -> String {\n    s.trim().to_uppercase()\n}");
    changeset_end(&a).unwrap();
    assert_eq!(review_state(&a, "reviewed").len(), 2);
    assert!(changesets(&b).unwrap().is_empty());

    let r = transfer(&a, &b, cs).unwrap();
    assert_eq!(r.sent, 2);
    assert_eq!(r.import.unwrap().diverged_at, None);
    assert!(std::fs::read_to_string(b_dir.path().join("src/main.rs")).unwrap().contains("read_file("));
    assert_eq!(review_state(&a, "reviewed"), review_state(&b, "reviewed"));
    assert_eq!(resolve_changeset(&b, "reviewed").unwrap().id, cs);
    assert_eq!(transfer(&a, &b, cs).unwrap().sent, 0, "nothing new to send");

    // A follow-up joins the same group and is the only thing sent.
    changeset_reopen(&a, cs).unwrap();
    rename_to(&a, "validate", "check");
    changeset_end(&a).unwrap();
    assert_eq!(transfer(&a, &b, cs).unwrap().sent, 1);
    assert_eq!(review_state(&a, "reviewed"), review_state(&b, "reviewed"));

    // The reviewer's own op on b comes back to a.
    changeset_reopen(&b, cs).unwrap();
    rename_to(&b, "parse", "parse_config");
    changeset_end(&b).unwrap();
    assert_eq!(transfer(&b, &a, cs).unwrap().sent, 1);
    assert!(std::fs::read_to_string(a_dir.path().join("src/main.rs")).unwrap().contains("parse_config("));
    let state = review_state(&a, "reviewed");
    assert_eq!(state.len(), 4);
    assert_eq!(state, review_state(&b, "reviewed"));

    // A prefix or a name resolves; an unknown one is refused.
    assert_eq!(resolve_changeset(&a, &cs.short()[..4]).unwrap().id, cs);
    assert!(resolve_changeset(&a, "nope").is_err());
}

