    #[test]
    fn resolve_take_help_names_the_sides() {
        let mut cmd = Cli::command();
        let help = cmd
            .find_subcommand_mut("resolve")
            .expect("resolve")
            .render_long_help()
            .to_string();
        assert!(help.contains("current change"), "{help}");
        assert!(help.contains("merged-in"), "{help}");
    }
